            prev=None; pending_order=1; i+=1; continue
        if t.startswith('['):
            m=re.match(r"\[([0-9]*)([A-Za-z][a-z]?|se|as)",t[1:-1]) or re.match(r"\[([0-9]*)([A-Za-z][a-z]?)",t)
            sym=m.group(2) if m else 'C'
            ch=re.search(r"([+-]\d*|[+-]+)\s*$",t[1:-1])
            charge=0
            if ch:
                c=ch.group(1)
                charge=(len(c)-1)*(-1) if set(c)<=set('-') else (len(c)-1)
                if c.lstrip('+-').isdigit(): charge=int(c)
            aromatic = 'ar' in t[1:-1]
            atoms.append((sym.capitalize(), charge, aromatic))
        else:
            sym=t
            aromatic = sym[0].islower()
            atoms.append((sym.capitalize(), 0, aromatic))
        idx=len(atoms)-1
        if prev is not None:
            bonds[(min(prev,idx),max(prev,idx))]=pending_order
        pending_order=1; prev=idx; i+=1
    return atoms,bonds

def wl_hash(smiles, rounds=4):
    atoms,bonds=parse(smiles)
    n=len(atoms)
    if n==0: return ()
    adj=[[0]*n for _ in range(n)]
    for (i,j),o in bonds.items(): adj[i][j]=adj[j][i]=1
    labels=[f"{a[0]}{a[1]}{'a' if a[2] else ''}" for a in atoms]
    for _ in range(rounds):
        labels=[labels[i]+"|"+"".join(sorted(labels[j] for j in range(n) if adj[i][j])) for i in range(n)]
    return tuple(sorted(labels))

def components(smiles):
    return [p.strip() for p in smiles.strip().split('.') if p.strip()]

def canonical_multiset(smiles):
    return tuple(sorted(wl_hash(c) for c in components(smiles)))

def heavy(smiles):
    return Counter(a[0] for a in parse(smiles)[0])
