import json, re, sys
sys.path.insert(0,'/workspace/harness/solver')
import answer_conventions as ac
from law import *
MEM=json.load(open(f'{root}/LawBench/memory.json'))
PROF=MEM['answer_profile']
INV=PROF['items']
ANSWERS=PROF['answers']

def fragments(s):
    """all contiguous pieces of s split at any separator"""
    parts=re.split(r'[;；,，、]', s)
    return [p for p in parts if p]

def expanded_vocab():
    """known wording: items, plus the fragments inside items, plus the items inside answers"""
    known={}
    for item,count in INV.items():
        known.setdefault(item,('item',count))
        for f in fragments(item):
            known.setdefault(f,('fragment',count))
    # also fragments of complete answers that never became items? items already cover them
    return known

def closest(item, known, maxdrift=3):
    low=item.lower(); best=None
    for key,(kind,count) in known.items():
        if abs(len(key)-len(low))>maxdrift: continue
        if key in low or low in key:
            score=(len(key),count)
            if best is None or score>best[0]: best=(score,key,kind,count)
    return None if best is None else (best[1],best[2],best[3])

def items_of(ans):
    return ac.answer_items(ans)

def notice2(answer, known):
    lines=[]
    for it in items_of(answer):
        if it.lower() in {k.lower() for k in known}: continue
        v=closest(it,known)
        if not v: continue
        key,kind,count=v
        comps=[a for a in ANSWERS if key in fragments(a) or key==a]
        comps=[c for c in comps if c!=key]
        if kind=='fragment' or comps:
            srcs = [a for a in ANSWERS if key in fragments(a)]
            if srcs:
                lines.append((it,key,f'writes "{key}" inside the complete answer(s) '+', '.join('"%s"'%s for s in sorted(srcs)[:2])))
            else:
                lines.append((it,key,f'writes "{key}"'))
        else:
            lines.append((it,key,f'writes "{key}"'))
    return lines
