import sys; sys.path.insert(0,'/tmp/an')
from law import *
import re, json, collections
tr=traces('LawBench')
def txt(m):
    c=m['content']; return c if isinstance(c,str) else ''.join(p.get('text','') for p in c if isinstance(p,dict))
def fa(x):
    try:
        j=json.loads(x[x.index('{'):x.rindex('}')+1]); return j.get('reasoning',''), j.get('final_answer','')
    except Exception: return '', x
def items(s):
    s=re.sub(r'<eoa>.*','',s,flags=re.S); s=re.sub(r'\[罪名\]','',s).strip()
    for sep in [';','；',',','，','、']:
        if sep in s: return [p.strip() for p in s.split(sep) if p.strip()]
    return [s] if s else []
def variants(s):
    """all prefixes of s of length len(s)-1..len(s)-2"""
    return [s[:-k] for k in (1,2) if len(s)-k>=2]
stat=collections.Counter(); rows=[]
for (i,s),t in sorted(tr.items()):
    n=len(t['messages'])
    if n<5: continue
    r,a=fa(txt(t['messages'][-2]))
    if not r: continue
    P=items(a); T=set(items(t['target']))
    flagged=[]
    for it in P:
        for v in variants(it):
            if v in r and it not in T and v in T:
                flagged.append((it,v)); break
    if flagged:
        stat['correct' if t['was_correct'] else 'wrong']+=1
        rows.append((i,s,t['was_correct'],flagged,t['target'],a[:50]))
print('samples where an answer item trims to a reasoning-attested target item:',dict(stat))
for e in rows: print('  ex%d s%d correct=%s %s | targ=%s | ans=%s'%(e[0],e[1],e[2],e[3],e[4][:45],e[5]))
# how many wrong samples have answer item = target-item + extra chars, regardless of reasoning
stat2=collections.Counter()
for (i,s),t in sorted(tr.items()):
    if len(t['messages'])<5: continue
    r,a=fa(txt(t['messages'][-2]))
    P=items(a); T=set(items(t['target']))
    loose=[it for it in P if it not in T and any(it.startswith(x) or x.startswith(it) for x in T)]
    if loose: stat2[('correct' if t['was_correct'] else 'wrong')]+=1
print('samples with an answer item near a target item (prefix-wise):',dict(stat2))
