import sys; sys.path.insert(0,'/tmp/an')
from law import *
import collections, math, json
mem=json.load(open(f'{root}/LawBench/memory.json'))['examples']
qs=[e['raw_question'] for e in mem]; ans=[e['target'] for e in mem]
def grams(s,n):
    s=re.sub(r'\s+','',s); return collections.Counter(s[i:i+n] for i in range(len(s)-n+1))
for n in [1,2,3,4]:
    G=[grams(q,n) for q in qs]; df=collections.Counter()
    for g in G: df.update(g.keys())
    N=len(G)
    def vec(g): return {k: v*math.log(1+N/df[k]) for k,v in g.items() if df[k]}
    V=[vec(g) for g in G]
    def sim(a,b):
        c=set(a)&set(b); num=sum(a[k]*b[k] for k in c)
        na=math.sqrt(sum(v*v for v in a.values())); nb=math.sqrt(sum(v*v for v in b.values()))
        return num/(na*nb+1e-9)
    # leave-one-out: is own answer among top-k other examples with same answer?
    hits={5:0,10:0,20:0,55:0}
    for i in range(N):
        order=sorted((j for j in range(N) if j!=i), key=lambda j: -sim(V[i],V[j]))
        for k in hits:
            if any(ans[j]==ans[i] for j in order[:k]): hits[k]+=1
    print('n=%d leave-one-out coverage (train):'%n, {k:'%.2f'%(v/N) for k,v in hits.items()})
